rd2:reload(twig_dk, 0.7)
function dk(pts)
  local g = {}
  for i,p in ipairs(pts) do g[#g+1] = {p[1], p[2], rd2:pressure_for(p[3])} end
  if rd2:fullness() < 0.35 then rd2:reload(twig_dk, 0.7) end
  rd2:gesture(g, {wobble=0})
end
